        "abstract": "単一項の二項分布確率を返します。 BINOMDIST 関数は、テストや試行の回数が固定されている問題で、どの試行の結果も成功または失敗のみで表される場合、各試行が独立している場合、および試行全体をとおして成功の確率が一定である場合に使用します。 たとえば、二男一女が生まれてくる確率などを BINOMDIST で計算できます。",
